"""Algorithm 1 — the apparition index of a good prime, via the reduced curve."""

from __future__ import annotations

from fractions import Fraction
from typing import Optional, Tuple

FinPoint = Optional[Tuple[int, int]]


def fin_add(P: FinPoint, Q: FinPoint, L: int) -> FinPoint:
    """Group law of E_N : y^2 = x^3 + N over the field with L elements."""
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2:
        if (y1 + y2) % L == 0:
            return None                                  # P = -Q
        lam = (3 * x1 * x1) * pow(2 * y1, -1, L) % L      # duplication
    else:
        lam = (y2 - y1) * pow(x2 - x1, -1, L) % L         # chord
    x3 = (lam * lam - x1 - x2) % L
    return (x3, (lam * (x1 - x3) - y1) % L)


def reduce_point(P: Tuple[Fraction, Fraction], L: int) -> FinPoint:
    """Reduce an L-integral rational point of E_N modulo L; None if it is already
    in the denominator kernel (i.e. reduces to the point at infinity)."""
    x, y = P
    if x.denominator % L == 0 or y.denominator % L == 0:
        return None
    return (x.numerator * pow(x.denominator, -1, L) % L,
            y.numerator * pow(y.denominator, -1, L) % L)


def apparition_index(P: Tuple[Fraction, Fraction], N: int, L: int) -> int:
    """The apparition index of the good prime L (>= 5, L not dividing N) for the point P:
    the least m > 0 with L | den x(mP).  It equals the order of the reduction of P in
    E_N(F_L), and is guaranteed by the effective apparition theorem to satisfy m <= 4L.

    Complexity: O(L) group operations naively, O(sqrt(L)) with baby-step/giant-step;
    each group operation costs O(log^2 L) bit operations.  Independent of how far along
    the rational orbit the prime first appears.
    """
    if L < 5 or N % L == 0:
        raise ValueError("L must be a prime >= 5 of good reduction (L does not divide N)")
    base = reduce_point(P, L)
    if base is None:
        return 1
    Q: FinPoint = base
    m = 1
    while Q is not None:
        if m > 4 * L:
            raise RuntimeError("effective bound 4L exceeded — input was not a good prime")
        Q = fin_add(Q, base, L)
        m += 1
    return m


if __name__ == "__main__":
    P = (Fraction(9), Fraction(28))          # on y^2 = x^3 + 55
    for L in (7, 13, 17, 19, 43, 73, 179):
        print(f"apparition index of {L:4d}: {apparition_index(P, 55, L)}")

"""Algorithm 2 — the denominator prime spectrum of an initial segment of an orbit."""

from __future__ import annotations

from fractions import Fraction
from math import isqrt
from typing import Dict, List, Optional, Tuple

FinPoint = Optional[Tuple[int, int]]


def primes_up_to(n: int) -> List[int]:
    sieve = bytearray([1]) * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, isqrt(n) + 1):
        if sieve[p]:
            sieve[p * p:: p] = bytearray(len(sieve[p * p:: p]))
    return [i for i in range(n + 1) if sieve[i]]


def fin_add(P: FinPoint, Q: FinPoint, L: int) -> FinPoint:
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2:
        if (y1 + y2) % L == 0:
            return None
        lam = (3 * x1 * x1) * pow(2 * y1, -1, L) % L
    else:
        lam = (y2 - y1) * pow(x2 - x1, -1, L) % L
    x3 = (lam * lam - x1 - x2) % L
    return (x3, (lam * (x1 - x3) - y1) % L)


def apparition_index(P: Tuple[Fraction, Fraction], L: int) -> int:
    x, y = P
    base: FinPoint = (x.numerator * pow(x.denominator, -1, L) % L,
                      y.numerator * pow(y.denominator, -1, L) % L)
    Q: FinPoint = base
    m = 1
    while Q is not None:
        Q = fin_add(Q, base, L)
        m += 1
    return m


def denominator_spectrum(P: Tuple[Fraction, Fraction], N: int,
                         orbit_length: int, prime_bound: int) -> Dict[int, List[int]]:
    """For every good prime L <= prime_bound, return the list of indices n <= orbit_length
    at which L divides den x(nP).

    By the apparition law that list is exactly the set of multiples of the apparition index
    m_L, of size floor(orbit_length / m_L).  The whole spectrum is therefore obtained from
    pi(prime_bound) finite-field computations, at cost O(pi(B) * sqrt(B)) group operations
    and *independently of orbit_length* — whereas computing the rational orbit directly
    would require exact arithmetic with integers of Theta(n^2) digits.
    """
    spectrum: Dict[int, List[int]] = {}
    for L in primes_up_to(prime_bound):
        if L < 5 or N % L == 0:
            continue
        m = apparition_index(P, L)
        spectrum[L] = [n for n in range(m, orbit_length + 1, m)]
    return spectrum


if __name__ == "__main__":
    P = (Fraction(9), Fraction(28))
    spec = denominator_spectrum(P, 55, orbit_length=30, prime_bound=100)
    for L, hits in sorted(spec.items()):
        if hits:
            print(f"{L:4d} | {hits}")
